package com.finance.controller;
import com.finance.model.Budget;import com.finance.repository.BudgetRepository;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import java.util.List;
@RestController @RequestMapping("/api/budgets") public class BudgetController {private final BudgetRepository repo;public BudgetController(BudgetRepository r){repo=r;}public record Request(@NotBlank String category,@Positive long limitPaise,@NotBlank @jakarta.validation.constraints.Pattern(regexp="\\d{4}-(0[1-9]|1[0-2])") String month){}@GetMapping public List<Budget> all(Authentication a){return repo.findByUserId(uid(a));}@PostMapping public Budget create(@Valid @RequestBody Request r,Authentication a){Budget b=new Budget();b.setUserId(uid(a));apply(b,r);return repo.save(b);}@PutMapping("/{id}") public Budget update(@PathVariable String id,@Valid @RequestBody Request r,Authentication a){Budget b=repo.findByIdAndUserId(id,uid(a)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));apply(b,r);return repo.save(b);}@DeleteMapping("/{id}") public void delete(@PathVariable String id,Authentication a){repo.delete(repo.findByIdAndUserId(id,uid(a)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND)));}private void apply(Budget b,Request r){b.setCategory(r.category());b.setLimitPaise(r.limitPaise());b.setMonth(r.month());}private String uid(Authentication a){return (String)a.getPrincipal();}}
